CREATE TABLE `resource_grants` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`resource_type` VARCHAR(40) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`grantee_membership_id` CHAR(36) CHARACTER SET ascii NOT NULL,`grantor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`reason` VARCHAR(500) NOT NULL,`status` ENUM('active','revoked') NOT NULL DEFAULT 'active',`expires_at` DATETIME(3) NOT NULL,`revoked_at` DATETIME(3) NULL,`revoked_by` CHAR(36) CHARACTER SET ascii NULL,`revocation_reason` VARCHAR(500) NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_resource_grants_grantee`(`organization_id`,`grantee_membership_id`,`status`,`expires_at`),KEY `idx_resource_grants_resource`(`organization_id`,`workspace_id`,`resource_type`,`resource_id`,`status`,`expires_at`),KEY `idx_resource_grants_created`(`organization_id`,`created_at`,`id`),CONSTRAINT `fk_resource_grants_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grants_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grants_grantee` FOREIGN KEY(`grantee_membership_id`) REFERENCES `memberships`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grants_grantor` FOREIGN KEY(`grantor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grants_revoker` FOREIGN KEY(`revoked_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
